x-test-examples.powershell:
# PowerShell - Calculer itinéraire par coordonnées
$headers = @{
    'Content-Type' = 'application/json'
    'Authorization' = 'Bearer YOUR_JWT_TOKEN'
}
$body = @{
    origin = @{
        name = 'Gare Casa Voyageurs'
        latitude = 33.5883
        longitude = -7.6114
        city = 'Casablanca'
    }
    destination = @{
        name = 'Gare Rabat Ville'
        latitude = 34.0181
        longitude = -6.8326
        city = 'Rabat'
    }
    includeReturn = $true
    userId = 'user123'
} | ConvertTo-Json -Depth 3

Invoke-RestMethod -Uri 'http://localhost:8082/api/routes/coordinates' -Method POST -Headers $headers -Body $body

x-test-examples.curl:
# cURL - Calculer itinéraire par coordonnées
curl -X POST 'http://localhost:8082/api/routes/coordinates' \
  -H 'Content-Type: application/json' \
  -H 'Authorization: Bearer YOUR_JWT_TOKEN' \
  -d '{
    "origin": {
      "name": "Gare Casa Voyageurs",
      "latitude": 33.5883,
      "longitude": -7.6114,
      "city": "Casablanca"
    },
    "destination": {
      "name": "Gare Rabat Ville",
      "latitude": 34.0181,
      "longitude": -6.8326,
      "city": "Rabat"
    },
    "includeReturn": true,
    "userId": "user123"
  }'

x-test-examples.fetch:
// JavaScript Fetch - Calculer itinéraire par coordonnées
const response = await fetch('http://localhost:8082/api/routes/coordinates', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer YOUR_JWT_TOKEN'
  },
  body: JSON.stringify({
    origin: {
      name: 'Gare Casa Voyageurs',
      latitude: 33.5883,
      longitude: -7.6114,
      city: 'Casablanca'
    },
    destination: {
      name: 'Gare Rabat Ville',
      latitude: 34.0181,
      longitude: -6.8326,
      city: 'Rabat'
    },
    includeReturn: true,
    userId: 'user123'
  })
});
const data = await response.json();
console.log(data);

